{
  "openapi": "3.1.0",
  "info": {
    "title": "PMO Portfolio Prioritization API",
    "description": "Portfolio data, data entry, uploads, pipeline control, PMO decisions, and quick-add intake for the PMO Portfolio Prioritization solution. OneLake (the Fabric lakehouse) is the only data store.",
    "version": "1.0.0"
  },
  "paths": {
    "/v1/health": {
      "get": {
        "tags": [
          "health"
        ],
        "summary": "Process status and lake data availability",
        "operationId": "getHealth",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/HealthResponse"
                }
              }
            }
          }
        }
      }
    },
    "/v1/options": {
      "get": {
        "tags": [
          "options"
        ],
        "summary": "Data-entry contract: option lists, field rules, and upload rules",
        "operationId": "getOptions",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/OptionsResponse"
                }
              }
            }
          }
        }
      }
    },
    "/v1/portfolio": {
      "get": {
        "tags": [
          "portfolio"
        ],
        "summary": "Portfolio export (contract v2), unchanged",
        "operationId": "getPortfolioExport",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {}
              }
            }
          },
          "404": {
            "description": "The export is missing. The problem names the OneLake path and the pipeline."
          }
        }
      }
    },
    "/v1/portfolios": {
      "get": {
        "tags": [
          "portfolio"
        ],
        "summary": "Portfolios from the export plus pending entries",
        "operationId": "listPortfolios",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/PortfolioList"
                }
              }
            }
          }
        }
      },
      "post": {
        "tags": [
          "portfolio"
        ],
        "summary": "Create a portfolio entry (pending until the pipeline runs)",
        "operationId": "createPortfolio",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "key": {
                    "type": "string",
                    "minLength": 3,
                    "maxLength": 40,
                    "description": "Portfolio key"
                  },
                  "displayName": {
                    "type": "string",
                    "minLength": 3,
                    "maxLength": 80,
                    "description": "Portfolio name"
                  },
                  "code": {
                    "type": "string",
                    "minLength": 2,
                    "maxLength": 8,
                    "description": "Portfolio code"
                  },
                  "role": {
                    "type": "string",
                    "enum": [
                      "main",
                      "coupled"
                    ],
                    "description": "Role"
                  },
                  "jiraProjectKey": {
                    "anyOf": [
                      {
                        "type": "string",
                        "maxLength": 10
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "JIRA project key"
                  },
                  "adoAreaRoot": {
                    "anyOf": [
                      {
                        "type": "string",
                        "maxLength": 20
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "ADO area root"
                  },
                  "programs": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "key": {
                          "type": "string"
                        },
                        "displayName": {
                          "type": "string"
                        },
                        "code": {
                          "type": "string"
                        }
                      },
                      "required": [
                        "key",
                        "displayName",
                        "code"
                      ],
                      "additionalProperties": false
                    },
                    "minItems": 1,
                    "maxItems": 10,
                    "description": "Programs"
                  }
                },
                "additionalProperties": false,
                "required": [
                  "key",
                  "displayName",
                  "code",
                  "role",
                  "programs"
                ]
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/PortfolioView"
                }
              }
            }
          },
          "422": {
            "description": "Validation Error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/HTTPValidationError"
                }
              }
            }
          }
        }
      }
    },
    "/v1/projects": {
      "get": {
        "tags": [
          "projects"
        ],
        "summary": "Processed and pending projects",
        "operationId": "listProjects",
        "parameters": [
          {
            "name": "portfolio",
            "in": "query",
            "required": false,
            "schema": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "description": "Portfolio key or code",
              "title": "Portfolio"
            },
            "description": "Portfolio key or code"
          },
          {
            "name": "role",
            "in": "query",
            "required": false,
            "schema": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "description": "main or coupled",
              "title": "Role"
            },
            "description": "main or coupled"
          },
          {
            "name": "confidence",
            "in": "query",
            "required": false,
            "schema": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "description": "High, Medium, or Low",
              "title": "Confidence"
            },
            "description": "High, Medium, or Low"
          },
          {
            "name": "q",
            "in": "query",
            "required": false,
            "schema": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "description": "Text match on ID, name, sponsor, or project manager",
              "title": "Q"
            },
            "description": "Text match on ID, name, sponsor, or project manager"
          },
          {
            "name": "page",
            "in": "query",
            "required": false,
            "schema": {
              "type": "integer",
              "minimum": 1,
              "default": 1,
              "title": "Page"
            }
          },
          {
            "name": "pageSize",
            "in": "query",
            "required": false,
            "schema": {
              "anyOf": [
                {
                  "type": "integer",
                  "minimum": 1
                },
                {
                  "type": "null"
                }
              ],
              "title": "Pagesize"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Page_ProjectListItem_"
                }
              }
            }
          },
          "422": {
            "description": "Validation Error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/HTTPValidationError"
                }
              }
            }
          }
        }
      },
      "post": {
        "tags": [
          "projects"
        ],
        "summary": "Create a project entry, assign its GIS number, and start the pipeline",
        "operationId": "createProject",
        "parameters": [
          {
            "name": "runPipeline",
            "in": "query",
            "required": false,
            "schema": {
              "type": "boolean",
              "description": "Start the pipeline after the entry is written",
              "default": true,
              "title": "Runpipeline"
            },
            "description": "Start the pipeline after the entry is written"
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "projectName": {
                    "type": "string",
                    "minLength": 3,
                    "maxLength": 120,
                    "description": "Project name"
                  },
                  "portfolioKey": {
                    "type": "string",
                    "description": "Portfolio"
                  },
                  "programKey": {
                    "type": "string",
                    "description": "Program"
                  },
                  "businessUnit": {
                    "type": "string",
                    "enum": [
                      "Semiconductor Process Equipment",
                      "Fab Operations",
                      "Global Supply Chain",
                      "Digital Transformation",
                      "Finance and Controls",
                      "Human Resources",
                      "Information Security",
                      "Manufacturing Engineering",
                      "Customer Services",
                      "Corporate IT"
                    ],
                    "description": "Business unit"
                  },
                  "site": {
                    "type": "string",
                    "enum": [
                      "Fremont",
                      "Tualatin",
                      "Singapore",
                      "Penang",
                      "Hsinchu",
                      "Global Remote"
                    ],
                    "description": "Site"
                  },
                  "sponsorName": {
                    "type": "string",
                    "minLength": 3,
                    "maxLength": 80,
                    "description": "Executive sponsor"
                  },
                  "sponsorEmail": {
                    "anyOf": [
                      {
                        "type": "string"
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Sponsor email"
                  },
                  "projectManager": {
                    "anyOf": [
                      {
                        "type": "string",
                        "maxLength": 80
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Project manager"
                  },
                  "projectStatus": {
                    "type": "string",
                    "enum": [
                      "Planning",
                      "Active",
                      "On Hold",
                      "Backlog"
                    ],
                    "description": "Status"
                  },
                  "goLiveDate": {
                    "type": "string",
                    "format": "date",
                    "description": "Go-live date"
                  },
                  "businessValue": {
                    "type": "integer",
                    "minimum": 1.0,
                    "maximum": 5.0,
                    "description": "Business value estimate (1 to 5)"
                  },
                  "userBase": {
                    "type": "integer",
                    "minimum": 0.0,
                    "maximum": 100000000.0,
                    "description": "User base (number of users)"
                  },
                  "estimatedAnnualBenefitUsd": {
                    "anyOf": [
                      {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 10000000000.0
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Estimated annual benefit (USD)"
                  },
                  "sponsorLevel": {
                    "type": "string",
                    "enum": [
                      "Executive",
                      "Director",
                      "Manager",
                      "Individual"
                    ],
                    "description": "Sponsor level"
                  },
                  "regulatorySecurity": {
                    "type": "boolean",
                    "description": "Regulatory or security driven"
                  },
                  "dtAlignment": {
                    "type": "boolean",
                    "description": "Digital transformation aligned"
                  },
                  "protectedProgram": {
                    "anyOf": [
                      {
                        "type": "boolean"
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Protected program"
                  },
                  "primarySkill": {
                    "type": "string",
                    "enum": [
                      "UC",
                      "NET",
                      "APP",
                      "DATA",
                      "CLOUD",
                      "SEC",
                      "INT",
                      "PM"
                    ],
                    "description": "Primary skill"
                  },
                  "skillDemandFte": {
                    "type": "number",
                    "minimum": 0.5,
                    "maximum": 12.0,
                    "description": "Skill demand (FTE)"
                  },
                  "costEstimateUsd": {
                    "type": "number",
                    "minimum": 10000.0,
                    "maximum": 100000000.0,
                    "description": "Cost estimate (USD)"
                  },
                  "dependencies": {
                    "anyOf": [
                      {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "projectId": {
                              "type": "string"
                            },
                            "relationshipType": {
                              "type": "string",
                              "enum": [
                                "FinishToStart",
                                "StartToStart",
                                "SharedResource",
                                "DataDependency",
                                "SecurityGate"
                              ]
                            }
                          },
                          "required": [
                            "projectId",
                            "relationshipType"
                          ],
                          "additionalProperties": false
                        },
                        "maxItems": 10
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Dependencies"
                  },
                  "riskRating": {
                    "type": "string",
                    "enum": [
                      "Low",
                      "Medium",
                      "High",
                      "Critical"
                    ],
                    "description": "Risk rating"
                  },
                  "effortPersonWeeks": {
                    "type": "number",
                    "minimum": 1.0,
                    "maximum": 2000.0,
                    "description": "Effort (person-weeks)"
                  },
                  "notes": {
                    "anyOf": [
                      {
                        "type": "string",
                        "maxLength": 1000
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "description": "Notes"
                  }
                },
                "additionalProperties": false,
                "required": [
                  "projectName",
                  "portfolioKey",
                  "programKey",
                  "businessUnit",
                  "site",
                  "sponsorName",
                  "projectStatus",
                  "goLiveDate",
                  "businessValue",
                  "userBase",
                  "sponsorLevel",
                  "regulatorySecurity",
                  "dtAlignment",
                  "primarySkill",
                  "skillDemandFte",
                  "costEstimateUsd",
                  "riskRating",
                  "effortPersonWeeks"
                ]
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ProjectCreated"
                }
              }
            }
          },
          "422": {
            "description": "Validation Error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/HTTPValidationError"
                }
              }
            }
          }
        }
      }
    },
